import React from "react";
import "./ProductList.scss";

const Product = ({ product }) => {
  if (!product) {
    return <div className="product">Produto não encontrado.</div>;
  }

  // Define a imagem do produto (caso brandImageUrl seja null, usa um placeholder)
  const imageUrl = product.brandImageUrl || "https://via.placeholder.com/250?text=Imagem+Indisponível";

  return (
    <div className="product">
      <img src={imageUrl} alt={product.productName} />
      <h3>{product.productName}</h3>
      <p><strong>Título:</strong> {product.productTitle}</p>
      <p><strong>Descrição:</strong> {product.metaTagDescription}</p>
    </div>
  );
};

export default Product;
